'use server';

import { revalidatePath } from 'next/cache';

// In-memory store for demonstration (replace with database in production)
const userPreferences = new Map<string, boolean>();

/**
 * Get the current notification preference for a user
 */
export async function getNotificationPreference(userId: string): Promise<boolean> {
  return userPreferences.get(userId) ?? false;
}

/**
 * Toggle the notification preference for a user
 * Uses revalidatePath to refresh the current page without redirecting
 */
export async function toggleNotificationPreference(userId: string): Promise<{ success: boolean; enabled: boolean }> {
  try {
    // Get current preference
    const currentPreference = userPreferences.get(userId) ?? false;

    // Toggle the preference
    const newPreference = !currentPreference;
    userPreferences.set(userId, newPreference);

    // Revalidate the current path to refresh the page data
    // This is Next.js's recommended approach for refreshing without redirecting
    revalidatePath('/');

    return {
      success: true,
      enabled: newPreference,
    };
  } catch (error) {
    console.error('Failed to toggle notification preference:', error);
    return {
      success: false,
      enabled: false,
    };
  }
}

