import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  // Fetch the current notification preference (uses demo userId: 'user-1')
  const notificationsEnabled = await getNotificationPreference('user-1');

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>

      <div style={{
        marginTop: '2rem',
        padding: '1.5rem',
        border: '1px solid #ddd',
        borderRadius: '8px',
        maxWidth: '500px'
      }}>
        <h2 style={{ marginTop: 0 }}>Notification Preferences</h2>

        <div style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginTop: '1rem'
        }}>
          <div>
            <strong>Email Notifications</strong>
            <p style={{ margin: '0.25rem 0 0 0', fontSize: '0.9rem', color: '#666' }}>
              Status: <span style={{
                color: notificationsEnabled ? '#16a34a' : '#dc2626',
                fontWeight: 'bold'
              }}>
                {notificationsEnabled ? 'Enabled' : 'Disabled'}
              </span>
            </p>
          </div>

          <form action={async () => {
            'use server';
            await toggleNotificationPreference('user-1');
          }}>
            <button
              type="submit"
              style={{
                padding: '0.5rem 1.5rem',
                backgroundColor: notificationsEnabled ? '#dc2626' : '#16a34a',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontWeight: '500',
                fontSize: '1rem'
              }}
            >
              Turn {notificationsEnabled ? 'Off' : 'On'}
            </button>
          </form>
        </div>
      </div>

      <div style={{
        marginTop: '1.5rem',
        padding: '1rem',
        backgroundColor: '#f0f9ff',
        borderLeft: '4px solid #0ea5e9',
        maxWidth: '500px'
      }}>
        <p style={{ margin: 0, fontSize: '0.9rem' }}>
          <strong>How it works:</strong> Click the button to toggle your notification preference.
          The page will refresh automatically using <code>revalidatePath('/')</code> to show
          the updated status without redirecting to a different page.
        </p>
      </div>
    </main>
  );
}

